function unlockAudio(){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return false;if(!audioCtx)audioCtx=new C();if(audioCtx.state==='suspended')audioCtx.resume();if(!masterGain){masterGain=audioCtx.createGain();masterGain.gain.value=.68;masterGain.connect(audioCtx.destination)}audioReady=true;return true}catch(e){return false}}
