 if(pos&&typeof player!=='undefined'){const dx=pos.x-player.x,dz=pos.z-player.z,dist=Math.hypot(dx,dz);attenuation=1/(1+dist*.045);const rightX=Math.cos(yaw),rightZ=-Math.sin(yaw);pan=Math.max(-1,Math.min(1,(dx*rightX+dz*rightZ)/(dist||1)))}
