 const tone=(freq,endFreq,duration,wave='sawtooth',gain=.2,delay=0)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=wave;o.frequency.setValueAtTime(Math.max(30,freq),now+delay);o.frequency.exponentialRampToValueAtTime(Math.max(30,endFreq),now+delay+duration);g.gain.setValueAtTime(.001,now+delay);g.gain.exponentialRampToValueAtTime(Math.max(.002,gain*1.7),now+delay+.008);g.gain.exponentialRampToValueAtTime(.001,now+delay+duration);o.connect(g);g.connect(out);o.start(now+delay);o.stop(now+delay+duration+.025)};
 const noise=(duration,filterFreq=1200,gain=.22)=>{const n=Math.max(1,Math.floor(audioCtx.sampleRate*duration)),buf=audioCtx.createBuffer(1,n,audioCtx.sampleRate),data=buf.getChannelData(0);for(let i=0;i<n;i++)data[i]=(Math.random()*2-1)*(1-i/n);const src=audioCtx.createBufferSource(),f=audioCtx.createBiquadFilter(),g=audioCtx.createGain();f.type='lowpass';f.frequency.value=filterFreq;g.gain.setValueAtTime(gain*1.7,now);g.gain.exponentialRampToValueAtTime(.001,now+duration);src.buffer=buf;src.connect(f);f.connect(g);g.connect(out);src.start(now);src.stop(now+duration)};
