 try{if('speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(clean);u.lang='ko-KR';u.rate=priority==='urgent'?1.12:1.06;u.pitch=priority==='urgent'?1.2:1.14;u.volume=1;const voices=speechSynthesis.getVoices();const v=voices.find(x=>/^ko[-_]KR/i.test(x.lang)&&/남|민준|인준|Male|Hyun|Jinho/i.test(x.name))||voices.find(x=>/^ko[-_]KR/i.test(x.lang));if(v)u.voice=v;speechSynthesis.speak(u)}}catch(e){}
