function aimedBuilding(){const dir=new THREE.Vector3(0,0,-1).applyEuler(camera.rotation).normalize();return buildings.filter(b=>b.side===team&&player.distanceTo(b.pos)<13).map(b=>({b,d:b.pos.clone().add(new THREE.Vector3(0,1,0)).sub(camera.position),distance:player.distanceTo(b.pos)})).filter(x=>x.d.normalize().dot(dir)>.985).sort((x,z)=>x.distance-z.distance)[0]?.b||null}
function updateAimTarget(){const info=$('#targetInfo');if(!info)return;const dir=new THREE.Vector3(0,0,-1).applyEuler(camera.rotation).normalize();let best=null,bestDist=Infinity;if(cls.id==='engineer'){for(const b of buildings){if(b.side!==team)continue;const delta=b.pos.clone().add(new THREE.Vector3(0,1,0)).sub(camera.position),dist=delta.length();if(dist<16&&delta.normalize().dot(dir)>.982&&dist<bestDist){best={type:'building',item:b};bestDist=dist}}}if(cls.id==='medic'){for(const b of bots){if(!b.alive||b.side!==team)continue;const delta=b.pos.clone().add(new THREE.Vector3(0,1,0)).sub(camera.position),dist=delta.length();if(dist<25&&delta.normalize().dot(dir)>.986&&dist<bestDist){best={type:'ally',item:b};bestDist=dist}}}if(best){const b=best.item;info.style.display='block';info.innerHTML=best.type==='building'?'<b>'+b.kind.toUpperCase().replace('TELEPORTERENTRANCE','TELEPORTER ENTRANCE').replace('TELEPORTEREXIT','TELEPORTER EXIT')+'</b><span>LEVEL '+b.level+' · HP '+Math.ceil(b.hp)+' / '+b.maxHp+'</span><div class="ally-health-track"><i style="width:'+Math.max(0,b.hp/b.maxHp*100)+'%;background:'+(b.hp/b.maxHp<.35?'#e34c43':'#77c96b')+'"></i></div>'+(cls.id==='engineer'&&wi===2?(b.hp<b.maxHp?'<small>렌치 클릭: '+Math.min(40,b.maxHp-b.hp)+' HP 수리 · 철제 '+Math.ceil(Math.min(40,b.maxHp-b.hp)/2)+'</small>':b.level<3?'<small>렌치 클릭: 업그레이드 · 철제 200</small>':'<small>최대 레벨 · 렌치로 수리 가능</small>'):''):'<b>'+b.cls.ko.toUpperCase()+'</b><span>ALLY HEALTH · '+Math.ceil(b.hp)+' / '+b.max+'</span><div class="ally-health-track"><i style="width:'+Math.max(0,b.hp/b.max*100)+'%"></i></div>'}else info.style.display='none'}
