 const target=bots.filter(b=>b.alive&&b.side!==team&&b.pos.distanceTo(sentryMesh.position)<18).sort((a,b)=>a.pos.distanceTo(sentryMesh.position)-b.pos.distanceTo(sentryMesh.position))[0];
