const NAV_STEP=4,NAV_MIN_X=-108,NAV_MIN_Z=-76,NAV_W=55,NAV_H=39,NAV_COUNT=NAV_W*NAV_H,navBlocked=new Uint8Array(NAV_W*NAV_H);
